    // Release (.aab): themes are delivered as Play Asset Delivery packs.
    assetPacks += themePacks.map { ":${it.name}" }

    // Debug (.apk): Play isn't there to deliver packs, so bundle every theme into the APK.
    sourceSets["debug"].assets.srcDirs(themePacks.map { it.resolve("src/main/assets") })

    compileOptions {
